<?php namespace App\Models; use App\Enums\AiJobStatus; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany}; class AiJob extends Model {protected $guarded=[]; protected function casts():array{return ['status'=>AiJobStatus::class,'started_at'=>'datetime','completed_at'=>'datetime'];} public function paper():BelongsTo{return $this->belongsTo(Paper::class);} public function requests():HasMany{return $this->hasMany(AiRequest::class);}}